<?php require_once __DIR__.'/includes/layout.php';if($u=current_user())go($u['rol'].'/dashboard.php');$role=($_GET['rol']??$_POST['rol']??'paciente')==='medico'?'medico':'paciente';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$ident=trim($_POST['ident']??'');$pass=$_POST['password']??'';$key=$role==='medico'?'m.cedula':'p.curp';$join=$role==='medico'?'medicos m':'pacientes p';$sql="SELECT u.id,u.password_hash,u.activo,u.rol FROM usuarios u JOIN $join ON $key=? AND ".($role==='medico'?'m.usuario_id':'p.usuario_id')."=u.id WHERE u.rol=?";$r=row($sql,[$ident,$role]);if($r&&$r['activo']&&password_verify($pass,$r['password_hash'])){session_regenerate_id(true);$_SESSION['uid']=$r['id'];go($role.'/dashboard.php');}else{$error='Los datos son incorrectos o la cuenta está desactivada.';}}
header_ui('Iniciar sesión'); ?>
